         o.created_by as manual_created_by
  from (
    select d.date, d.isrc, d.streams_cumulative, d.source_run_id, d.created_at as base_created_at
    from public.track_daily_streams d
    where d.date >= public.stream_history_hot_from()
    union all
    select c.d as date, m.isrc, m.vals[extract(day from c.d)::int] as streams_cumulative,
           null::uuid as source_run_id, null::timestamptz as base_created_at
    from (select date '2025-01-01' + g.i as d from generate_series(0, 4017) as g(i)
          where date '2025-01-01' + g.i < public.stream_history_hot_from()) c
    join public.track_streams_monthly m on m.month = date_trunc('month', c.d)::date
    where m.vals[extract(day from c.d)::int] is not null
  ) t
  left join public.track_daily_stream_overrides o on o.date = t.date and o.isrc = t.isrc
  union all
  select a.date,
         a.isrc,
         coalesce(o.streams_cumulative_override, a.streams_cumulative) as streams_cumulative,
         null::uuid as source_run_id,
         null::timestamptz as base_created_at,
         (o.id is not null) as is_manual_override,
         o.id as override_id,
         o.note as manual_note,
         o.created_at as manual_created_at,
         o.created_by as manual_created_by
  from public.track_daily_streams_archive a
  left join public.track_daily_stream_overrides_all o on o.date = a.date and o.isrc = a.isrc
  where a.date < public.stream_compact_from()
  union all
  select o.date,
         o.isrc,
         o.streams_cumulative_override as streams_cumulative,
         null::uuid as source_run_id,
         null::timestamptz as base_created_at,
         true as is_manual_override,
         o.id as override_id,
         o.note as manual_note,
         o.created_at as manual_created_at,
         o.created_by as manual_created_by
  from public.track_daily_stream_overrides_all o
  where (o.date >= public.stream_compact_from() or o.base_missing)
    and not exists (select 1 from public.track_daily_streams t
